CREATE TABLE IF NOT EXISTS farmer_farms(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,name TEXT NOT NULL DEFAULT 'আমার খামার',total_area_value REAL DEFAULT 0,total_area_unit TEXT DEFAULT 'decimal',soil_type TEXT,water_source TEXT,location TEXT,division TEXT,district TEXT,upazila TEXT,union_name TEXT,area_name TEXT,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS farm_journal_entries(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,entry_text TEXT NOT NULL,source_type TEXT NOT NULL DEFAULT 'text',audio_path TEXT,parsed_json TEXT,parse_status TEXT NOT NULL DEFAULT 'pending',needs_confirmation INTEGER DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS farm_plots(id TEXT PRIMARY KEY,farm_id TEXT NOT NULL,name TEXT NOT NULL,area_value REAL NOT NULL,area_unit TEXT NOT NULL DEFAULT 'decimal',area_decimal REAL NOT NULL DEFAULT 0,land_type TEXT,soil_type TEXT,water_source TEXT,location TEXT,tenure TEXT,active INTEGER DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,closed_at TEXT,close_reason TEXT);
CREATE TABLE IF NOT EXISTS plot_crops(id TEXT PRIMARY KEY,plot_id TEXT NOT NULL,crop_id TEXT,variety_id TEXT,crop_name TEXT NOT NULL,variety_name TEXT,planting_date TEXT,area_value REAL,area_unit TEXT DEFAULT 'decimal',area_decimal REAL,season TEXT,status TEXT NOT NULL DEFAULT 'active',harvest_date TEXT,notes TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS farm_activity_records(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,plot_id TEXT,crop_instance_id TEXT,activity_type TEXT NOT NULL,activity_date TEXT NOT NULL,details TEXT NOT NULL,quantity_value REAL,quantity_unit TEXT,source_journal_id TEXT,confidence REAL DEFAULT 1.0,needs_confirmation INTEGER DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS farm_input_records(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,plot_id TEXT,crop_instance_id TEXT,input_type TEXT NOT NULL,input_name TEXT NOT NULL,quantity_value REAL,quantity_unit TEXT,application_date TEXT,notes TEXT,source_journal_id TEXT,confidence REAL DEFAULT 1.0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS farm_area_history(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,farm_id TEXT NOT NULL,plot_id TEXT,change_type TEXT NOT NULL,old_area_value REAL,old_area_unit TEXT,old_area_decimal REAL,new_area_value REAL,new_area_unit TEXT,new_area_decimal REAL,reason TEXT,effective_date TEXT NOT NULL,source_journal_id TEXT,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_farmer_farms_user ON farmer_farms(user_id,status);
CREATE INDEX IF NOT EXISTS idx_farm_plots_farm_active ON farm_plots(farm_id,active);
CREATE INDEX IF NOT EXISTS idx_plot_crops_plot_status ON plot_crops(plot_id,status,planting_date);
CREATE INDEX IF NOT EXISTS idx_farm_activity_user_date ON farm_activity_records(user_id,activity_date);
CREATE INDEX IF NOT EXISTS idx_farm_input_user_date ON farm_input_records(user_id,application_date);
CREATE INDEX IF NOT EXISTS idx_farm_area_history_farm_date ON farm_area_history(farm_id,effective_date);
CREATE INDEX IF NOT EXISTS idx_farm_journal_user_date ON farm_journal_entries(user_id,created_at);
